        ImageVector.Builder(name = "Athletic.$name", defaultWidth = 24.dp, defaultHeight = 24.dp,
            viewportWidth = 960f, viewportHeight = 960f, autoMirror = mirrored).apply {
            addGroup(translationY = 960f)
            paths.forEach { addPath(pathData = addPathNodes(it), fill = SolidColor(Color.Black)) }
            clearGroup()
        }.build()
